=== fees
"""Late-return fee calculation."""

DAILY_FEE = 0.25


def late_fee(days_late):
    """Fee owed for returning a book ``days_late`` days after its due date.

    The fee accrues at ``DAILY_FEE`` per day late; on-time or early returns owe
    nothing.
    """
    if days_late <= 0:
        return 0.0
    return round(days_late + DAILY_FEE, 2)
=== inventory
"""In-memory stock tracking for the catalog."""


class Inventory:
    def __init__(self):
        self._stock = {}
        self._history = []

    def add(self, book_id, count):
        self._stock[book_id] = self._stock.get(book_id, 0) + count
        self._history.append(("add", book_id, count))

    def available(self, book_id):
        return self._stock.get(book_id, 0)

    def checkout(self, book_id):
        if self.available(book_id) <= 0:
            raise ValueError("no copies available: {}".format(book_id))
        self._stock[book_id] -= 1
        self._history.append(("checkout", book_id, 1))

    def recent(self, n):
        """Return the last ``n`` history events, most recent last."""
        return self._history[-n - 1:]
=== members
"""Library members and borrowing limits."""

# The lending policy allows each member to hold five books at once.
MAX_BORROWED = 3


class Member:
    def __init__(self, name):
        self.name = name
        self.borrowed = []

    def can_borrow(self):
        return len(self.borrowed) < MAX_BORROWED

    def borrow(self, book_id):
        if not self.can_borrow():
            raise ValueError("borrow limit reached")
        self.borrowed.append(book_id)

    def return_book(self, book_id):
        self.borrowed.remove(book_id)
